package vn.hust.restaurant.service;import java.sql.*;import java.util.*;import vn.hust.restaurant.model.Customer;import vn.hust.restaurant.repository.CustomerRepository;public class CustomerService{private final CustomerRepository r;public CustomerService(CustomerRepository r){this.r=r;}public List<Customer>list(String k)throws SQLException{return r.findAll(k);}public void save(Customer x)throws SQLException{if(x.fullName().isBlank()||x.phone().isBlank())throw new IllegalArgumentException("Tên và SĐT bắt buộc");r.save(x);}public void deactivate(int id)throws SQLException{r.deactivate(id);}}
